from pathlib import Path
import json,hashlib
from PIL import Image
O=Path(__file__).resolve().parents[1];R=O/'reviews';P=O/'candidates/round-02'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
floorp=O/'source/resources/context-floor-cream.png';humanp=O/'source/resources/context-chef-lena-S.png';floor=Image.open(floorp).convert('RGBA');human=Image.open(humanp).convert('RGBA')
assert floor.size==(256,256)and human.size==(384,640)
out={'packetSHA256':sha(P/'packet.json'),'scope':'Independent supplemental contexts, exact sealed native RGBA compositing only. No sealed file modified.','inputs':[{'path':str(p.relative_to(O)),'sha256':sha(p)}for p in [floorp,humanp]+sorted((P/'frames').glob('*/*.png'))],'contexts':[]}
def canvas(grid,origin,size):
 im=Image.new('RGBA',size,(48,52,60,255))
 for y in range(grid[1]):
  for x in range(grid[0]):im.alpha_composite(floor,(origin[0]+256*x,origin[1]+256*y))
 return im
def place(im,p,root,anchor):im.alpha_composite(Image.open(p).convert('RGBA'),(root[0]-anchor[0],root[1]-anchor[1]))
for d in ['N','E','S','W']:
 frame=P/f'frames/idle-{d}/000.png'
 im=canvas((7,4),(0,512),(1792,1536));roots=[(512,768),(1024,768)]
 for root in roots:place(im,frame,root,(448,704))
 n=f'round02-judge-repeated-{d}-native.png';im.save(R/n)
 for label,s in [('logical',2),('phone',4)]:im.resize((1792//s,1536//s),Image.Resampling.LANCZOS).save(R/n.replace('native',label))
 out['contexts'].append({'kind':'independent-repetition','direction':d,'outputs':[{'path':str(p.relative_to(O)),'sha256':sha(p),'size':list(Image.open(p).size)}for p in [R/n,R/n.replace('native','logical'),R/n.replace('native','phone')]],'nativePitch':256,'sourceScale':2,'grid':[7,4],'gridOriginNative':[0,512],'sofaRootsNative':roots,'rawFrameAnchorNative':[448,704],'sampling':'Whole native frame RGBA compositing at identity; then uniform whole-context2x/4x LANCZOS for logical/phone.'})
# Literal catalog example: x/y are footprint top-left cell coordinates; roots use authored directionRootCells.
im=canvas((5,3),(256,512),(1792,1536));sofaroot=(512,768);humanroot=(1152,640);place(im,P/'frames/idle-S/000.png',sofaroot,(448,704));place(im,humanp,humanroot,(192,496));n='round02-judge-literal-catalog-native.png';im.save(R/n)
for label,s in [('logical',2),('phone',4)]:im.resize((1792//s,1536//s),Image.Resampling.LANCZOS).save(R/n.replace('native',label))
out['contexts'].append({'kind':'literal-catalog-human-placement','catalogPlacements':[{'object':'garbage-sofa','cell':[0,0],'rootCell':[1,1]},{'object':'chef-lena','cell':[3,0],'rootCell':[.5,.5]}],'grid':[5,3],'gridOriginNative':[256,512],'nativePitch':256,'sourceScale':2,'sofaRootNative':sofaroot,'humanRootNative':humanroot,'sofaAnchorNative':[448,704],'humanAnchorNative':[192,496],'outputs':[{'path':str(p.relative_to(O)),'sha256':sha(p),'size':list(Image.open(p).size)}for p in [R/n,R/n.replace('native','logical'),R/n.replace('native','phone')]]})
html='''<!doctype html><meta charset="utf-8"><title>Sofa judge registered floor playback</title><style>body{font:14px system-ui;background:#30343c;color:white;margin:12px}main{display:grid;grid-template-columns:448px 448px;gap:8px}canvas{width:448px;height:384px}#metrics{font-size:12px}</style><h1>Independent registered floor playback</h1><p>Exact sealed moving native frames; original cream floor and registered human. Full context at half-logical size; each sofa frame224×288. All4facings. 12fps, highlighted loops, clearance one shot with opaque native endpoint.</p><select id="clip"><option>highlighted</option><option>clearance</option></select> <button id="replay">Replay</button><p id="metrics">Loading</p><main></main><script>const dirs=['N','E','S','W'],imgs={},cvs={},all=[];for(const c of['highlighted','clearance']){imgs[c]={};for(const d of dirs){imgs[c][d]=[];for(let i=0;i<12;i++){const im=new Image();im.src='../candidates/round-02/frames/'+c+'-'+d+'/'+String(i).padStart(3,'0')+'.png';imgs[c][d].push(im);all.push(im)}}}const floor=new Image();floor.src='../source/resources/context-floor-cream.png';const human=new Image();human.src='../source/resources/context-chef-lena-S.png';all.push(floor,human);for(const d of dirs){const box=document.createElement('div');box.textContent=d;const cv=document.createElement('canvas');cv.width=448;cv.height=384;box.append(cv);document.querySelector('main').append(box);cvs[d]=cv}let start=0;document.querySelector('#replay').onclick=()=>start=performance.now();document.querySelector('#clip').onchange=()=>start=performance.now();Promise.all(all.map(im=>im.decode())).then(()=>{start=performance.now();requestAnimationFrame(tick)});function tick(now){const t=Math.max(0,Math.floor((now-start)*12/1000)),clip=document.querySelector('#clip').value,f=clip==='highlighted'?t%12:Math.min(11,t);for(const d of dirs){const ctx=cvs[d].getContext('2d');ctx.fillStyle='#30343c';ctx.fillRect(0,0,448,384);for(let y=0;y<3;y++)for(let x=0;x<5;x++)ctx.drawImage(floor,64+64*x,128+64*y,64,64);ctx.drawImage(imgs[clip][d][f],16,16,224,288);ctx.drawImage(human,240,36,96,160)}document.querySelector('#metrics').textContent=JSON.stringify({allDecoded:all.every(im=>im.complete&&im.naturalWidth),clip,fps:12,elapsedMs:Math.round(now-start),index:f,highlightedWraps:Math.floor(t/12),terminalHold:clip==='clearance'&&t>=12,sofaRootNative:[512,768],humanRootNative:[1152,640],pitchNative:256,sourceScale:2,contextScale:.25});requestAnimationFrame(tick)}</script>'''
p=R/'round02-judge-floor-playback.html';p.write_text(html);out['temporalPlayer']={'path':str(p.relative_to(O)),'sha256':sha(p),'sourceFrames':96,'directions':['N','E','S','W'],'fps':12,'contextNativeSize':[1792,1536],'contextCanvas':[448,384],'sofaRootNative':[512,768],'humanRootNative':[1152,640],'nativePitch':256,'sourceScale':2,'frameSampling':'Complete original896x1152 frame rendered224x288; scale.25 for whole registered context.','url':'http://127.0.0.1:4178/prototypes/sushi-loop/assets/refinement/objects/garbage-sofa/reviews/round02-judge-floor-playback.html'}
(R/'round02-judge-context-evidence.json').write_text(json.dumps(out,indent=2)+'\n');print('CONTEXTS',len(out['contexts']))
